    expect(lstat(platep, &st) == 0 && S_ISREG(st.st_mode),
           "the plate path is a regular file after the empty augogen file");
    tf = fopen(platep, "rb");
    n = 0;
    buf[0] = 0;
    if (tf) {
      n = fread(buf, 1, sizeof buf - 1, tf);
      fclose(tf);
    }
    buf[n] = 0;
